package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.RetentionDaysVO;

class RetentionDaysValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retention days of observed source")
  void test_retention_days_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetentionDaysValueHolder<Object> value = new RetentionDaysValueHolder<>(holder);
    Assertions.assertSame(holder, value.retentionDays(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionDaysValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetentionDays().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.retentionDaysNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionDaysValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getRetentionDays().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retention days of observed source")
  void test_retention_days_value_holder_assign_value_object() {
    Object holder = new Object();
    RetentionDaysValueHolder<Object> value = new RetentionDaysValueHolder<>(holder);
    RetentionDaysVO vo = RetentionDaysVO.from(1);
    Assertions.assertFalse(value.getRetentionDaysValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.retentionDays(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetentionDaysValue().orElseThrow());
    Assertions.assertSame(holder, value.retentionDays(Optional.empty()));
    Assertions.assertFalse(value.getRetentionDaysValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retentionDays(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetentionDaysValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retention days of observed source against the original")
  void test_retention_days_value_holder_read() {
    Object holder = new Object();
    RetentionDaysValueHolder<Object> value = new RetentionDaysValueHolder<>(holder);
    RetentionDaysVO vo = RetentionDaysVO.from(1);
    RetentionDaysVO other = RetentionDaysVO.from(1);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getRetentionDaysValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetentionDays(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readRetentionDays(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.retentionDays(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetentionDays(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetentionDays(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retention days of observed source")
  void test_retention_days_value_holder_unset() {
    Object holder = new Object();
    RetentionDaysValueHolder<Object> value = new RetentionDaysValueHolder<>(holder);
    RetentionDaysVO vo = RetentionDaysVO.from(1);
    value.retentionDays(vo);
    Assertions.assertSame(holder, value.unsetRetentionDaysIfMatches("retentionDays_other"));
    Assertions.assertTrue(value.getRetentionDaysValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetentionDaysIfMatches("retentionDays"));
    Assertions.assertFalse(value.getRetentionDaysValue().isPresent(),
        "The field name must clear the value");
    value.retentionDays(vo);
    Assertions.assertSame(holder, value.unsetRetentionDays());
    Assertions.assertFalse(value.getRetentionDaysValue().isPresent(), "Unset must clear the value");
  }
}
